SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;

CREATE SCHEMA IF NOT EXISTS kol_gov;
SET search_path TO kol_gov, public;

DROP TABLE IF EXISTS kol_gov.crawl_runs;

CREATE TABLE IF NOT EXISTS influencers (
    influencer_key text PRIMARY KEY,
    name text NOT NULL,
    nick_name text,
    gender text,
    identity_verified boolean NOT NULL DEFAULT false,
    avatar_url text,
    source_url text NOT NULL,
    scraped_at timestamptz NOT NULL
);

CREATE TABLE IF NOT EXISTS social_channels (
    channel_key text PRIMARY KEY,
    influencer_key text NOT NULL REFERENCES influencers(influencer_key) ON DELETE CASCADE,
    channel_type text,
    channel_name text,
    channel_url text,
    followers bigint,
    views bigint,
    likes bigint,
    posts_count integer,
    videos_count integer,
    scraped_at timestamptz NOT NULL
);

ALTER TABLE influencers ADD COLUMN IF NOT EXISTS avatar_url text;
ALTER TABLE social_channels ADD COLUMN IF NOT EXISTS posts_count integer;
ALTER TABLE social_channels ADD COLUMN IF NOT EXISTS videos_count integer;

CREATE TABLE IF NOT EXISTS mcn_owners (
    source_id text PRIMARY KEY,
    name text,
    subtitle text,
    avatar_url text,
    platforms jsonb NOT NULL DEFAULT '[]'::jsonb,
    channels_by_type jsonb NOT NULL DEFAULT '{}'::jsonb,
    total_channels integer,
    total_kols integer,
    raw_json jsonb NOT NULL,
    scraped_at timestamptz NOT NULL
);

CREATE TABLE IF NOT EXISTS influencer_posts (
    post_key text PRIMARY KEY,
    influencer_key text NOT NULL REFERENCES influencers(influencer_key) ON DELETE CASCADE,
    platform text NOT NULL,
    title text NOT NULL,
    thumbnail_url text,
    source_url text,
    views bigint,
    likes bigint,
    published_date date,
    display_order integer NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS mcn_featured_channels (
    featured_channel_key text PRIMARY KEY,
    mcn_source_id text NOT NULL REFERENCES mcn_owners(source_id) ON DELETE CASCADE,
    rank integer NOT NULL,
    name text NOT NULL,
    platform text NOT NULL,
    channel_url text NOT NULL,
    avatar_url text,
    interaction_value bigint,
    growth_rate numeric,
    UNIQUE (mcn_source_id, rank)
);

CREATE TABLE IF NOT EXISTS growth_rankings (
    snapshot_key text PRIMARY KEY,
    entity_type text NOT NULL,
    source_id text NOT NULL,
    metric text NOT NULL,
    period_days integer NOT NULL,
    rank integer NOT NULL,
    name text,
    subtitle text,
    avatar_url text,
    snap_end_now bigint,
    growth_current bigint,
    growth_previous bigint,
    growth_change numeric,
    growth_rate numeric,
    score numeric,
    raw_json jsonb NOT NULL,
    scraped_at timestamptz NOT NULL
);

CREATE TABLE IF NOT EXISTS ticker_channels (
    source_channel_id text PRIMARY KEY,
    name text,
    followers bigint,
    likes bigint,
    views bigint,
    comments bigint,
    shares bigint,
    raw_json jsonb NOT NULL,
    scraped_at timestamptz NOT NULL
);

CREATE TABLE IF NOT EXISTS bsi_rankings (
    snapshot_key text PRIMARY KEY,
    tab text NOT NULL,
    year integer NOT NULL,
    month integer NOT NULL,
    rank integer NOT NULL,
    name text,
    score numeric,
    image_url text,
    raw_json jsonb NOT NULL,
    scraped_at timestamptz NOT NULL,
    UNIQUE (tab, year, month, rank)
);

CREATE TABLE IF NOT EXISTS news_posts (
    slug text PRIMARY KEY,
    source_url text NOT NULL UNIQUE,
    category text,
    title text NOT NULL,
    excerpt text,
    published_date date,
    reading_minutes integer,
    image_url text,
    body_text text,
    body_html text,
    tags jsonb NOT NULL DEFAULT '[]'::jsonb,
    scraped_at timestamptz NOT NULL
);

CREATE TABLE IF NOT EXISTS influencer_source_ids (
    source_id text PRIMARY KEY,
    source_system text NOT NULL,
    influencer_key text NOT NULL REFERENCES influencers(influencer_key) ON DELETE CASCADE,
    match_method text NOT NULL,
    confidence numeric(5,4) NOT NULL CHECK (confidence BETWEEN 0 AND 1),
    detail_url text NOT NULL,
    scraped_at timestamptz NOT NULL
);

CREATE TABLE IF NOT EXISTS mcn_influencers (
    membership_key text PRIMARY KEY,
    mcn_source_id text NOT NULL REFERENCES mcn_owners(source_id) ON DELETE CASCADE,
    influencer_key text NOT NULL REFERENCES influencers(influencer_key) ON DELETE CASCADE,
    influencer_source_id text NOT NULL REFERENCES influencer_source_ids(source_id) ON DELETE CASCADE,
    relationship_type text NOT NULL,
    source_url text NOT NULL,
    scraped_at timestamptz NOT NULL,
    UNIQUE (mcn_source_id, influencer_key, relationship_type)
);

CREATE TABLE IF NOT EXISTS growth_entities (
    growth_entity_key text PRIMARY KEY,
    entity_type text NOT NULL CHECK (entity_type IN ('influencer', 'owner')),
    source_id text NOT NULL,
    influencer_key text REFERENCES influencers(influencer_key) ON DELETE CASCADE,
    mcn_source_id text REFERENCES mcn_owners(source_id) ON DELETE CASCADE,
    display_name text,
    scraped_at timestamptz NOT NULL,
    CHECK (
        (entity_type = 'influencer' AND influencer_key IS NOT NULL AND mcn_source_id IS NULL)
        OR
        (entity_type = 'owner' AND influencer_key IS NULL AND mcn_source_id IS NOT NULL)
    ),
    UNIQUE (entity_type, source_id)
);

CREATE TABLE IF NOT EXISTS growth_ranking_entities (
    snapshot_key text PRIMARY KEY REFERENCES growth_rankings(snapshot_key) ON DELETE CASCADE,
    growth_entity_key text NOT NULL REFERENCES growth_entities(growth_entity_key) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS channel_entities (
    channel_entity_key text PRIMARY KEY,
    canonical_url text,
    normalized_name text,
    platform text,
    display_name text,
    scraped_at timestamptz NOT NULL
);

CREATE TABLE IF NOT EXISTS channel_entity_social_channels (
    channel_key text PRIMARY KEY REFERENCES social_channels(channel_key) ON DELETE CASCADE,
    channel_entity_key text NOT NULL REFERENCES channel_entities(channel_entity_key) ON DELETE CASCADE,
    match_method text NOT NULL
);

CREATE TABLE IF NOT EXISTS channel_entity_ticker_channels (
    source_channel_id text PRIMARY KEY REFERENCES ticker_channels(source_channel_id) ON DELETE CASCADE,
    channel_entity_key text NOT NULL REFERENCES channel_entities(channel_entity_key) ON DELETE CASCADE,
    match_method text NOT NULL,
    confidence numeric(5,4) NOT NULL CHECK (confidence BETWEEN 0 AND 1)
);

CREATE TABLE IF NOT EXISTS bsi_subjects (
    subject_key text PRIMARY KEY,
    subject_type text NOT NULL,
    name text,
    image_url text,
    influencer_key text REFERENCES influencers(influencer_key) ON DELETE SET NULL,
    match_method text,
    scraped_at timestamptz NOT NULL,
    UNIQUE (subject_type, name)
);

CREATE TABLE IF NOT EXISTS bsi_ranking_subjects (
    snapshot_key text PRIMARY KEY REFERENCES bsi_rankings(snapshot_key) ON DELETE CASCADE,
    subject_key text NOT NULL REFERENCES bsi_subjects(subject_key) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS news_categories (
    category_key text PRIMARY KEY,
    name text NOT NULL UNIQUE
);

CREATE TABLE IF NOT EXISTS news_post_categories (
    slug text PRIMARY KEY REFERENCES news_posts(slug) ON DELETE CASCADE,
    category_key text NOT NULL REFERENCES news_categories(category_key) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS news_tags (
    tag_key text PRIMARY KEY,
    name text NOT NULL UNIQUE
);

CREATE TABLE IF NOT EXISTS news_post_tags (
    news_post_tag_key text PRIMARY KEY,
    slug text NOT NULL REFERENCES news_posts(slug) ON DELETE CASCADE,
    tag_key text NOT NULL REFERENCES news_tags(tag_key) ON DELETE CASCADE,
    UNIQUE (slug, tag_key)
);

